class Node {
  constructor(val) {
    this.val = val;
    this.next = null;
    this.bottom = null;
  }
}

function mergeBottom(a, b) {
  const dummy = new Node(0);
  let tail = dummy;
  while (a && b) {
    if (a.val <= b.val) {
      tail.bottom = a;
      a = a.bottom;
    } else {
      tail.bottom = b;
      b = b.bottom;
    }
    tail = tail.bottom;
  }
  tail.bottom = a || b;
  return dummy.bottom;
}

function flatten(head) {
  if (!head || !head.next) return head;
  head.next = flatten(head.next);
  return mergeBottom(head, head.next);
}

function makeList(arr) {
  let head = null, tail = null;
  for (const v of arr) {
    const n = new Node(v);
    if (!head) head = tail = n;
    else {
      tail.bottom = n;
      tail = n;
    }
  }
  return head;
}
const l1 = makeList([5, 7, 8, 30]);
l1.next = makeList([10, 20]);
l1.next.next = makeList([19, 22, 50]);
l1.next.next.next = makeList([28, 35, 40, 45]);
const flat = flatten(l1);
const out = [];
for (let n = flat; n; n = n.bottom) out.push(n.val);
console.log(out.join(' '));

