struct Node {
    int v;
    Node*next, *child;
};
Node* flatten(Node*h) {
    if (!h)return h;
    Node*c=h;
    while (c) {
        if (c->child) {
            Node*ch=c->child, *nx=c->next;
            c->next=ch;
            Node*tail=flatten(ch);
            while (tail->next)tail=tail->next;
            tail->next=nx;
            c->child=nullptr;
        }
        c=c->next;
    }
    return h;
}
